package ru.trioz.connect

import org.amnezia.awg.config.Config
import java.io.BufferedReader
import java.io.StringReader

object VpnProfile {
    // Profiles are generated by our API. Never accept shell hooks, local files or app exclusions.
    fun withNativeKey(raw: String, privateKey: String): Config {
        require(raw.length in 1..32768)
        val forbidden = Regex("(?i)^\\s*(PreUp|PostUp|PreDown|PostDown|IncludedApplications|ExcludedApplications|ListenPort)\\s*=")
        require(raw.lineSequence().none { forbidden.containsMatchIn(it) })
        val keyLine = Regex("(?im)^\\s*PrivateKey\\s*=.*$")
        require(keyLine.findAll(raw).count() == 1)
        val replaced = keyLine.replace(raw, "PrivateKey = $privateKey")
        val config = Config.parse(BufferedReader(StringReader(replaced)))
        require(config.peers.size == 1 && config.`interface`.addresses.isNotEmpty())
        require(config.peers.all { it.endpoint.isPresent && it.allowedIps.isNotEmpty() })
        return config
    }
}
